from ibm_watsonx_ai.foundation_models import ModelInference
from langchain.agents import AgentType
from ibm_watsonx_ai.metanames import GenTextParamsMetaNames as GenParams
from ibm_watsonx_ai.foundation_models.utils.enums import ModelTypes
from ibm_watson_machine_learning.foundation_models.extensions.langchain import WatsonxLLM
from langchain_community.utilities.sql_database import SQLDatabase
from langchain_community.agent_toolkits import create_sql_agent

# model_id = 'ibm/granite-3-2-8b-instruct'
model_id = "ibm/granite-3-8b-instruct"

parameters = {
    GenParams.MAX_NEW_TOKENS: 256,  # This controls the maximum number of tokens in the generated output
    GenParams.TEMPERATURE: 0.5, # This randomness or creativity of the model's responses
}

credentials = {
    "url": "https://us-south.ml.cloud.ibm.com"
}

project_id = "skills-network"

model = ModelInference(
    model_id=model_id,
    params=parameters,
    credentials=credentials,
    project_id=project_id
)

granite_llm = WatsonxLLM(model = model)
# print(granite_llm.invoke("What is the capital of Ontario?"))
mysql_username = 'root'
mysql_password = 'iGWUqxBlIv4feeJcDbVhRKag' # Replace with your server connect information
mysql_host = '172.21.17.68' # Replace with your server connect information
mysql_port = '3306' # Replace with your server connect information
database_name = 'Chinook'
mysql_uri = f'mysql+mysqlconnector://{mysql_username}:{mysql_password}@{mysql_host}:{mysql_port}/{database_name}'
db = SQLDatabase.from_uri(mysql_uri)

agent_executor = create_sql_agent(
    llm=granite_llm, 
    db=db, 
    verbose=True, 
    handle_parsing_errors=True, 
    agent_type=AgentType.ZERO_SHOT_REACT_DESCRIPTION
)


